    if not isinstance(events, list):
        raise ValueError("events must be a list")

    results = []
    leases = {}
    expirations = []
    next_token = 1
    previous_time = -1

    for event in events:
        if not isinstance(event, tuple) or not event:
            raise ValueError("each event must be a nonempty tuple")

        action = event[0]
        if not isinstance(action, str):
            raise ValueError("invalid event action")

        if action == "acquire":
            expected_length = 5
        elif action == "renew":
            expected_length = 6
        elif action == "release":
            expected_length = 5
        else:
            raise ValueError("unknown event action")

        if len(event) != expected_length:
            raise ValueError("invalid event length")

        time, key, owner = event[1:4]
        if type(time) is not int or time < 0:
            raise ValueError("time must be a nonnegative exact int")
        if time < previous_time:
            raise ValueError("times must be nondecreasing")
        if not isinstance(key, str) or not isinstance(owner, str):
            raise ValueError("key and owner must be strings")

        if action == "acquire":
