def ragged_walk(rows: list[list[int]]) -> list[int]:
    remaining = {
        (r, c)
        for r, row in enumerate(rows)
        for c in range(len(row))
    }
    if not remaining:
        return []

    cell_order = (
        (r, c)
        for r, row in enumerate(rows)
        for c in range(len(row))
    )
    r, c = next(cell_order)
    directions = ((0, 1), (1, 0), (0, -1), (-1, 0))
    direction = 0
    result: list[int] = []

    while remaining:
        result.append(rows[r][c])
        remaining.remove((r, c))
        if not remaining:
            break

        for turn in range(4):
            candidate_direction = (direction + turn) % 4
            dr, dc = directions[candidate_direction]
            neighbor = (r + dr, c + dc)
            if neighbor in remaining:
                r, c = neighbor
                direction = candidate_direction
                break
        else:
            r, c = next(cell for cell in cell_order if cell in remaining)
            direction = 0

    return result

