import heapq


def dependency_waves(
    deps: dict[str, list[str]], cancelled: set[str], width: int
) -> list[list[str]]:
    """Schedule dependency waves after propagating cancellation."""
    if type(width) is not int or width <= 0:
        raise ValueError("width must be a positive exact int")

    names = set(deps)
    removed = set(cancelled)
    if removed - names:
        raise ValueError("Unknown cancelled names")

    dependencies: dict[str, set[str]] = {}
    dependents: dict[str, set[str]] = {name: set() for name in names}

    for name, listed_dependencies in deps.items():
        unique_dependencies = set(listed_dependencies)
        if unique_dependencies - names:
            raise ValueError("Unknown dependency names")
        dependencies[name] = unique_dependencies
        for dependency in unique_dependencies:
            dependents[dependency].add(name)

    pending = list(removed)
    while pending:
        removed_name = pending.pop()
        for dependent in dependents[removed_name]:
            if dependent not in removed:
                removed.add(dependent)
                pending.append(dependent)

    remaining = names - removed
    indegree = {name: len(dependencies[name]) for name in remaining}
    ready = [name for name in remaining if indegree[name] == 0]
    heapq.heapify(ready)

    waves: list[list[str]] = []
    scheduled_count = 0

    while ready:
        wave = [heapq.heappop(ready) for _ in range(min(width, len(ready)))]
        waves.append(wave)
        scheduled_count += len(wave)

        for name in wave:
            for dependent in dependents[name]:
                if dependent in remaining:
                    indegree[dependent] -= 1
                    if indegree[dependent] == 0:
                        heapq.heappush(ready, dependent)

    if scheduled_count != len(remaining):
        raise ValueError("Remaining dependencies contain a cycle")

    return waves

