def transaction_frames(
    initial: dict[str, int], commands: list[tuple]
) -> tuple[dict, list[bool]]:
    if not isinstance(initial, dict) or not isinstance(commands, list):
        raise ValueError("Expected a balance dictionary and a command list.")

    for account, balance in initial.items():
        if not isinstance(account, str):
            raise ValueError("Account names must be strings.")
        if type(balance) is not int or balance < 0:
            raise ValueError("Balances must be nonnegative exact integers.")

    balances = dict(initial)
    frames: list[tuple[dict[str, int], bool]] = []
    commits: list[bool] = []

    for command in commands:
        if (
            not isinstance(command, tuple)
            or not command
            or not isinstance(command[0], str)
        ):
            raise ValueError("Invalid command.")

        operation = command[0]

        if operation == "move":
            if len(command) != 4:
                raise ValueError("A move requires source, destination, and amount.")

            _, source, destination, amount = command

            if not isinstance(source, str) or not isinstance(destination, str):
                raise ValueError("Account names must be strings.")
            if type(amount) is not int or amount < 0:
                raise ValueError("Amounts must be nonnegative exact integers.")
            if source not in balances or destination not in balances:
                raise ValueError("Both accounts must exist.")

            if frames and frames[-1][1]:
                continue
            if source == destination:
                continue

            if balances[source] < amount:
                if frames:
                    parent_balances, _ = frames[-1]
                    frames[-1] = (parent_balances, True)
                continue

            balances[source] -= amount
            balances[destination] += amount

        elif operation in ("begin", "commit", "rollback"):
            if len(command) != 1:
                raise ValueError("Frame commands take no arguments.")

            if operation == "begin":
                if frames and frames[-1][1]:
                    raise ValueError("Cannot begin within a failed frame.")
                frames.append((balances, False))
                balances = balances.copy()
            else:
                if not frames:
                    raise ValueError("No frame is open.")

                parent_balances, failed = frames.pop()

                if operation == "rollback":
                    balances = parent_balances
                else:
                    commits.append(not failed)
                    if failed:
                        balances = parent_balances

        else:
            raise ValueError("Unknown command.")

    if frames:
        raise ValueError("Unbalanced frames.")

    return balances, commits

