    """Allocate an exact total using iterative capped largest remainders."""
    if type(total) is not int or total < 0:
        raise ValueError("total must be a nonnegative exact int")
    if not isinstance(weights, list) or not isinstance(caps, list):
        raise ValueError("weights and caps must be lists")
    if len(weights) != len(caps):
        raise ValueError("weights and caps must have equal lengths")
    if any(type(weight) is not int or weight < 0 for weight in weights):
        raise ValueError("weights must contain nonnegative exact ints")
    if any(type(cap) is not int or cap < 0 for cap in caps):
        raise ValueError("caps must contain nonnegative exact ints")

    if sum(cap for weight, cap in zip(weights, caps) if weight > 0) < total:
        raise ValueError("eligible capacity is less than total")

    allocations = [0] * len(weights)
    if total == 0:
        return allocations

    active = [
        index
        for index, (weight, cap) in enumerate(zip(weights, caps))
        if weight > 0 and cap > 0
    ]
