                amount = caps[index] - allocations[index]
                allocations[index] += amount
                remaining -= amount
            active = [
                index
                for index in active
                if allocations[index] < caps[index]
            ]
            continue

        remainders = []
        allocated_this_round = 0
        for index in active:
            floor_share, remainder = divmod(
                remaining * weights[index], weight_sum
            )
            allocations[index] += floor_share
            allocated_this_round += floor_share
            remainders.append((remainder, index))

