from zoneinfo import ZoneInfo


def wall_occurrences(start, stop, hour: int, minute: int) -> list:
    if type(hour) is not int or not 0 <= hour <= 23:
        raise ValueError("hour must be an exact int in 0..23")
    if type(minute) is not int or not 0 <= minute <= 59:
        raise ValueError("minute must be an exact int in 0..59")

    if not isinstance(start, datetime) or not isinstance(stop, datetime):
        raise ValueError("start and stop must be aware datetimes")
    if not isinstance(start.tzinfo, ZoneInfo):
        raise ValueError("start must use a ZoneInfo timezone")
    if not isinstance(stop.tzinfo, ZoneInfo):
        raise ValueError("stop must use a ZoneInfo timezone")
    if start.tzinfo is not stop.tzinfo:
        raise ValueError("start and stop must share the identical zone object")
    if start.utcoffset() is None or stop.utcoffset() is None:
        raise ValueError("start and stop must be aware")

    zone = start.tzinfo

    def utc_key(value):
        offset = value.utcoffset()
        local_microseconds = (
            (
                (value.toordinal() - 1) * 86400
                + value.hour * 3600
                + value.minute * 60
                + value.second
            )
            * 1_000_000
            + value.microsecond
        )
        offset_microseconds = (
            (offset.days * 86400 + offset.seconds) * 1_000_000
            + offset.microseconds
        )
        return local_microseconds - offset_microseconds

    start_key = utc_key(start)
    stop_key = utc_key(stop)
    if start_key > stop_key:
        raise ValueError("start must not be later than stop in UTC")
    if start_key == stop_key:
        return []

    current_date = start.date()
    final_date = stop.date()
    occurrences = {}

    while current_date <= final_date:
        wall = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            hour,
            minute,
        )
        first = wall.replace(tzinfo=zone, fold=0)
        second = wall.replace(tzinfo=zone, fold=1)

        for candidate in (first, second):
            key = utc_key(candidate)
            if not start_key <= key < stop_key or key in occurrences:
                continue

            try:
                returned = candidate.astimezone(timezone.utc).astimezone(zone)
            except OverflowError:
                # At datetime's boundaries, UTC may lie outside years 1..9999.
                # ZoneInfo assigns increasing fold offsets to forward gaps.
                if first.utcoffset() < second.utcoffset():
                    continue
                if first.utcoffset() == second.utcoffset():
                    returned = first
                else:
                    returned = candidate
            else:
                if returned.replace(tzinfo=None) != wall:
                    continue

            occurrences[key] = returned

        if current_date == final_date:
            break
        current_date += timedelta(days=1)

    return [occurrences[key] for key in sorted(occurrences)]

