def coupon_route(
    edges: list[tuple[str, str, int]],
    start: str,
    end: str,
    hops: int,
):
    if not isinstance(start, str) or not isinstance(end, str):
        raise ValueError("start and end must be strings")
    if type(hops) is not int or hops < 0:
        raise ValueError("hops must be a nonnegative exact integer")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")

    adjacency = {}
    nodes = {start, end}

    for edge in edges:
        if not isinstance(edge, tuple) or len(edge) != 3:
            raise ValueError("each edge must be a tuple of three elements")
        source, target, cost = edge
        if not isinstance(source, str) or not isinstance(target, str):
            raise ValueError("edge endpoints must be strings")
        if type(cost) is not int or cost < 0:
            raise ValueError("edge costs must be nonnegative exact integers")

        adjacency.setdefault(source, []).append((target, cost))
        nodes.add(source)
        nodes.add(target)

    if start == end:
        return 0, (start,)
    if hops == 0:
        return None

    # Removing any cycle cannot increase cost, even if the cycle contains
    # the discounted edge. The fewest-edge optimum is therefore simple.
    limit = min(hops, len(nodes) - 1)

    # Each layer represents exactly one edge count. Values compare by
    # cost first, then by the complete node tuple.
    current = {(start, False): (0, (start,))}
    best = None

    def retain(states, key, candidate):
        existing = states.get(key)
        if existing is None or candidate < existing:
            states[key] = candidate

    for edge_count in range(1, limit + 1):
        following = {}

        for (node, used_discount), (cost_so_far, path) in current.items():
            for target, edge_cost in adjacency.get(node, ()):
                next_path = path + (target,)
                retain(
                    following,
                    (target, used_discount),
                    (cost_so_far + edge_cost, next_path),
                )

                if not used_discount:
                    retain(
                        following,
                        (target, True),
                        (cost_so_far + edge_cost // 2, next_path),
                    )

        if not following:
            break

        for used_discount in (False, True):
            result = following.get((end, used_discount))
            if result is not None:
                candidate = (result[0], edge_count, result[1])
                if best is None or candidate < best:
                    best = candidate

        current = following

    if best is None:
        return None
    return best[0], best[2]

