def _mock_plan_construct(factory, values, fallback):
    signature = inspect.signature(factory)
    positional = []
    keywords = {}
    explicit_parameters = [
        parameter
        for parameter in signature.parameters.values()
        if parameter.kind
        not in (
            inspect.Parameter.VAR_POSITIONAL,
            inspect.Parameter.VAR_KEYWORD,
        )
    ]

    if not explicit_parameters:
        return factory(**fallback)

    for parameter in explicit_parameters:
        if parameter.name in values:
            value = values[parameter.name](parameter.annotation)
        elif parameter.default is not inspect.Parameter.empty:
            if parameter.kind is inspect.Parameter.POSITIONAL_ONLY:
                positional.append(parameter.default)
            continue
        else:
            raise TypeError(
                f"Unsupported required parameter "
                f"{factory.__name__}.{parameter.name}"
